import * as React from "react";
import {
  Alert,
  Box,
  Button,
  Paper,
  Stack,
  TextField,
  Typography,
} from "@mui/material";
import { useTranslation } from "gatsby-plugin-react-i18next";
import type { ContactRequest } from "../interfaces";
import { submitContactRequest } from "../services/contactRequest";
import { logEmailJsError } from "../services/emailJsError";
import { executeRecaptchaV3 } from "../services/recaptchaV3";

type ContactFormValues = ContactRequest & {
  company: string;
};

type ContactFormErrors = Partial<Record<keyof ContactFormValues, string>>;
type ContactFormTouched = Partial<Record<keyof ContactFormValues, boolean>>;

const initialFormValues: ContactFormValues = {
  name: "",
  email: "",
  phone: "",
  comments: "",
  company: "",
};

const textFieldSx = {
  "& .MuiInputLabel-root": {
    color: "rgba(0, 0, 0, 0.7)",
  },
  "& .MuiInputLabel-root.Mui-focused": {
    color: "#4ecdc4",
  },
  "& .MuiOutlinedInput-root": {
    borderRadius: "16px",
    backgroundColor: "rgba(247, 248, 238, 0.72)",
  },
  "& .MuiOutlinedInput-root.Mui-focused .MuiOutlinedInput-notchedOutline": {
    borderColor: "#4ecdc4",
  },
};

function isValidEmail(email: string) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function isValidName(name: string) {
  return /^[\p{L}\p{M}' .-]{2,80}$/u.test(name);
}

function isValidPhone(phone: string) {
  if (!/^[0-9+\s().-]+$/.test(phone)) {
    return false;
  }

  const digits = phone.replace(/\D+/g, "");
  return digits.length >= 7 && digits.length <= 15;
}

function toContactRequest(values: ContactFormValues): ContactRequest {
  return {
    name: values.name.trim(),
    email: values.email.trim(),
    phone: values.phone.trim(),
    comments: values.comments.trim(),
  };
}

export default function EmailForm() {
  const { t } = useTranslation();
  const [formValues, setFormValues] = React.useState(initialFormValues);
  const [formErrors, setFormErrors] = React.useState<ContactFormErrors>({});
  const [touchedFields, setTouchedFields] = React.useState<ContactFormTouched>({});
  const [isSubmitting, setIsSubmitting] = React.useState(false);
  const [status, setStatus] = React.useState<{
    severity: "success" | "error";
    message: string;
  } | null>(null);

  function translate(key: string) {
    return String(t(key));
  }

  function validate(values: ContactFormValues) {
    const nextErrors: ContactFormErrors = {};

    if (!values.name.trim()) {
      nextErrors.name = translate("contactForm.validation.required");
    } else if (!isValidName(values.name.trim())) {
      nextErrors.name = translate("contactForm.validation.invalidName");
    }

    if (!values.email.trim()) {
      nextErrors.email = translate("contactForm.validation.required");
    } else if (!isValidEmail(values.email.trim())) {
      nextErrors.email = translate("contactForm.validation.invalidEmail");
    }

    if (!values.phone.trim()) {
      nextErrors.phone = translate("contactForm.validation.required");
    } else if (!isValidPhone(values.phone.trim())) {
      nextErrors.phone = translate("contactForm.validation.invalidPhone");
    }

    if (values.comments.trim().length > 1200) {
      nextErrors.comments = translate("contactForm.validation.commentsTooLong");
    }

    return nextErrors;
  }

  function getFieldError(
    fieldName: keyof ContactFormValues,
    values: ContactFormValues,
  ) {
    return validate(values)[fieldName];
  }

  function handleFieldChange(
    event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>,
  ) {
    const { name, value } = event.target;
    const fieldName = name as keyof ContactFormValues;

    setFormValues((currentValues) => ({
      ...currentValues,
      [fieldName]: value,
    }));

    setFormErrors((currentErrors) => {
      if (!touchedFields[fieldName] && !currentErrors[fieldName]) {
        return currentErrors;
      }

      const nextErrors = { ...currentErrors };
      const nextFieldError = getFieldError(fieldName, {
        ...formValues,
        [fieldName]: value,
      });

      if (nextFieldError) {
        nextErrors[fieldName] = nextFieldError;
      } else {
        delete nextErrors[fieldName];
      }

      return nextErrors;
    });

    if (status) {
      setStatus(null);
    }
  }

  function handleFieldBlur(
    event: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement>,
  ) {
    const fieldName = event.target.name as keyof ContactFormValues;

    setTouchedFields((currentTouched) => ({
      ...currentTouched,
      [fieldName]: true,
    }));

    setFormErrors((currentErrors) => {
      const nextErrors = { ...currentErrors };
      const nextFieldError = getFieldError(fieldName, formValues);

      if (nextFieldError) {
        nextErrors[fieldName] = nextFieldError;
      } else {
        delete nextErrors[fieldName];
      }

      return nextErrors;
    });
  }

  function handleResetContactForm() {
    setFormValues(initialFormValues);
    setFormErrors({});
    setTouchedFields({});
    setStatus(null);
  }

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (formValues.company.trim()) {
      setFormValues(initialFormValues);
      setFormErrors({});
      setTouchedFields({});
      setStatus({
        severity: "success",
        message: translate("contactForm.status.success"),
      });
      return;
    }

    const nextErrors = validate(formValues);

    if (Object.keys(nextErrors).length > 0) {
      setTouchedFields({
        name: true,
        email: true,
        phone: true,
        comments: true,
      });
      setFormErrors(nextErrors);
      setStatus({
        severity: "error",
        message: translate("contactForm.status.validationError"),
      });
      return;
    }

    setIsSubmitting(true);
    setStatus(null);

    try {
      const recaptchaToken = await executeRecaptchaV3("contact_submit");

      await submitContactRequest(toContactRequest(formValues), recaptchaToken);
      setFormValues(initialFormValues);
      setFormErrors({});
      setTouchedFields({});
      setStatus({
        severity: "success",
        message: translate("contactForm.status.success"),
      });
    } catch (error) {
      logEmailJsError("Contact form submission failed", error);

      const isConfigError =
        error instanceof Error &&
        (error.message === "CONTACT_EMAIL_NOT_CONFIGURED" ||
          error.message === "RECAPTCHA_NOT_CONFIGURED");
      const isRecaptchaError =
        error instanceof Error &&
        (error.message === "RECAPTCHA_LOAD_FAILED" ||
          error.message === "RECAPTCHA_UNAVAILABLE" ||
          error.message === "RECAPTCHA_EXECUTION_FAILED");

      setStatus({
        severity: "error",
        message: isConfigError
          ? translate("contactForm.status.serviceUnavailable")
          : isRecaptchaError
            ? translate("contactForm.status.recaptchaError")
            : translate("contactForm.status.error"),
      });
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <Paper
      elevation={0}
      sx={{
        borderRadius: "28px",
        border: "1px solid rgba(78, 205, 196, 0.18)",
        background:
          "linear-gradient(180deg, rgba(247, 248, 238, 0.94) 0%, rgba(247, 248, 238, 0.88) 100%)",
        p: { xs: 3, md: 4 },
        boxShadow: "0 24px 60px rgba(0, 0, 0, 0.08)",
      }}
    >
      {status?.severity === "success" ? (
        <Stack spacing={3}>
          <Box>
            <Typography
              variant="h5"
              sx={{
                fontFamily: '"Libre Baskerville", Georgia, serif',
                color: "#ff6b6b",
                fontWeight: 700,
              }}
            >
              {t("contactForm.successView.title")}
            </Typography>
            <Typography sx={{ mt: 1, color: "rgba(0, 0, 0, 0.72)" }}>
              {t("contactForm.successView.body")}
            </Typography>
          </Box>

          <Alert severity="success">{status.message}</Alert>

          <Stack direction={{ xs: "column", sm: "row" }} spacing={2}>
            <Button
              type="button"
              variant="contained"
              onClick={handleResetContactForm}
              sx={styles.primaryButton}
            >
              {t("contactForm.successView.sendAnother")}
            </Button>

            <Button
              type="button"
              variant="outlined"
              href="/"
              sx={styles.secondaryButton}
            >
              {t("contactForm.successView.goHome")}
            </Button>
          </Stack>
        </Stack>
      ) : (
        <Stack component="form" spacing={3} onSubmit={handleSubmit} noValidate>
          <Box>
            <Typography
              variant="h5"
              sx={{
                fontFamily: '"Libre Baskerville", Georgia, serif',
                color: "#ff6b6b",
                fontWeight: 700,
              }}
            >
              {t("contactForm.title")}
            </Typography>
            <Typography sx={{ mt: 1, color: "rgba(0, 0, 0, 0.72)" }}>
              {t("contactForm.subtitle")}
            </Typography>
          </Box>

          {status ? <Alert severity={status.severity}>{status.message}</Alert> : null}

          <TextField
            label={t("contactForm.fields.name")}
            name="name"
            value={formValues.name}
            onChange={handleFieldChange}
            onBlur={handleFieldBlur}
            error={Boolean(formErrors.name)}
            helperText={formErrors.name}
            fullWidth
            required
            sx={textFieldSx}
          />

          <Box
            sx={{
              display: "grid",
              gap: 2,
              gridTemplateColumns: { xs: "1fr", md: "repeat(2, minmax(0, 1fr))" },
            }}
          >
            <TextField
              label={t("contactForm.fields.email")}
              name="email"
              type="email"
              value={formValues.email}
              onChange={handleFieldChange}
              onBlur={handleFieldBlur}
              error={Boolean(formErrors.email)}
              helperText={formErrors.email}
              fullWidth
              required
              sx={textFieldSx}
            />

            <TextField
              label={t("contactForm.fields.phone")}
              name="phone"
              type="tel"
              value={formValues.phone}
              onChange={handleFieldChange}
              onBlur={handleFieldBlur}
              error={Boolean(formErrors.phone)}
              helperText={formErrors.phone}
              fullWidth
              required
              sx={textFieldSx}
            />
          </Box>

          <TextField
            label={t("contactForm.fields.comments")}
            name="comments"
            value={formValues.comments}
            onChange={handleFieldChange}
            onBlur={handleFieldBlur}
            error={Boolean(formErrors.comments)}
            helperText={formErrors.comments || t("contactForm.fields.commentsHelper")}
            fullWidth
            multiline
            minRows={5}
            sx={textFieldSx}
          />

          <TextField
            label={t("contactForm.fields.company")}
            name="company"
            value={formValues.company}
            onChange={handleFieldChange}
            autoComplete="off"
            tabIndex={-1}
            sx={{ display: "none" }}
          />

          <Alert severity="info">{t("contactForm.recaptchaNotice")}</Alert>

          <Button
            type="submit"
            variant="contained"
            disabled={isSubmitting}
            sx={styles.primaryButton}
          >
            {isSubmitting
              ? t("contactForm.actions.submitting")
              : t("contactForm.actions.submit")}
          </Button>
        </Stack>
      )}
    </Paper>
  );
}

const styles = {
  primaryButton: {
    minHeight: 56,
    borderRadius: "999px",
    bgcolor: "#4ecdc4",
    color: "#0d3b37",
    fontWeight: 700,
    textTransform: "none",
    fontSize: "1rem",
    "&:hover": {
      bgcolor: "#39b7af",
    },
    "&.Mui-disabled": {
      bgcolor: "rgba(78, 205, 196, 0.45)",
      color: "rgba(13, 59, 55, 0.72)",
    },
  },
  secondaryButton: {
    minHeight: 56,
    borderRadius: "999px",
    borderColor: "rgba(78, 205, 196, 0.5)",
    color: "#0d3b37",
    fontWeight: 700,
    textTransform: "none",
    fontSize: "1rem",
    "&:hover": {
      borderColor: "#39b7af",
      backgroundColor: "rgba(78, 205, 196, 0.08)",
    },
  },
};
